command:
if (!game.user.isGM) return ui.notifications.warn('Restore Selected Unit(s) is GM-only.');

const units = (canvas.tokens?.controlled ?? []).filter(token => token.actor?.type === 'Character');
if (!units.length) return ui.notifications.warn('Select one or more units first.');
const reachLabel = units.length === 1
  ? units[0].actor.name : `the ${units.length} selected units`;

const proceed = await foundry.applications.api.DialogV2.wait({
  window: { title: 'Restore Selected Unit(s)' },
  classes: ['emblem-rpg', 'dialog-editor'],
  position: { width: 460 },
  content: `
    <div class="ed-container">
      <div class="ed-section ed-section--highlight">
        <p class="ed-description">Fully restore ${reachLabel}?</p>
      </div>
      <div class="ed-section">
        <p class="ed-description">Every unit in reach is set back to its maximum resources and a fresh turn.
          All temporary active effects are dispelled, leaving wielded, mounted and armor
          effects intact, and every item they carry that Refreshes is returned to full uses.</p>
      </div>
    </div>`,
  buttons: [
    { action: 'confirm', label: 'Restore', icon: 'fas fa-heart', callback: () => true },
    { action: 'cancel', label: 'Cancel', default: true, callback: () => false }
  ],
  rejectClose: false
});
if (!proceed) return;

const result = await game.emblemRpg.api.development.restoreUnits({
  scope: 'selection',
  actorUuids: units.map(token => token.actor.uuid)
});

console.group(`emblem-rpg | Restore Selected Unit(s) — ${result.ok ? 'settled' : 'refused'}`);
console.log(result.ok ? result.data : result);
console.groupEnd();
